INSERT INTO destinations (id, name, region, description, longitude, latitude) VALUES (1, 'Zermatt', 'Valais', 'A charming alpine village at the foot of the iconic Matterhorn, offering world-class skiing, hiking trails, and breathtaking mountain views. Car-free town with traditional Swiss chalets.', 7.7491, 46.0207);
INSERT INTO destinations (id, name, region, description, longitude, latitude) VALUES (2, 'Interlaken', 'Bernese Oberland', 'Adventure capital of Switzerland nestled between Lake Thun and Lake Brienz, surrounded by the majestic Eiger, Mönch, and Jungfrau peaks. Perfect for paragliding, hiking, and mountain excursions.', 7.8632, 46.6863);
INSERT INTO destinations (id, name, region, description, longitude, latitude) VALUES (3, 'Lucerne', 'Central Switzerland', 'Historic lakeside city famous for its medieval architecture, Chapel Bridge, and stunning lake views. Gateway to Mount Pilatus and Rigi, combining culture with natural beauty.', 8.3093, 47.0502);
INSERT INTO destinations (id, name, region, description, longitude, latitude) VALUES (4, 'Lausanne', 'Vaud', 'Vibrant lakefront city on Lake Geneva, known for the Olympic Museum, medieval old town, and terraced Lavaux vineyards. Cultural hub with contemporary museums and festivals.', 6.6323, 46.5197);
INSERT INTO destinations (id, name, region, description, longitude, latitude) VALUES (5, 'St. Moritz', 'Graubünden', 'Glamorous alpine resort town famous for luxury shopping, winter sports, and hosting the Winter Olympics twice. Crystal-clear mountain lakes and upscale dining experiences.', 9.8390, 46.4983);
INSERT INTO destinations (id, name, region, description, longitude, latitude) VALUES (6, 'Lugano', 'Ticino', 'Mediterranean-style Swiss city with Italian flair, palm-lined promenades, and lakeside parks. Mild climate perfect for exploring Monte Brè, shopping, and enjoying aperitivo culture.', 8.9511, 46.0037);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (1, 1, 'Matterhorn View Hotel', 280.00, 'Boutique hotel with panoramic Matterhorn views from every room. Features a spa, fine dining restaurant serving Swiss specialties, and ski-in access. Cozy fireplaces and alpine elegance.', 7.7486, 46.0213);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (2, 1, 'Alpine Lodge Zermatt', 150.00, 'Family-run chalet-style hotel offering warm hospitality and traditional Swiss breakfast. Walking distance to ski lifts and village center. Comfortable rooms with mountain views.', 7.7469, 46.0198);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (3, 2, 'Interlaken Grand Resort', 320.00, 'Luxury lakefront property with private beach access, infinity pool overlooking the mountains, and Michelin-starred restaurant. Spa with alpine wellness treatments.', 7.8550, 46.6866);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (4, 2, 'Adventure Base Hostel', 75.00, 'Modern hostel perfect for budget travelers and outdoor enthusiasts. Social atmosphere, communal kitchen, and organized adventure tours. Dorm and private room options.', 7.8685, 46.6850);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (5, 3, 'Lucerne Palace Hotel', 295.00, 'Historic Belle Époque hotel on the lakefront with elegant rooms, marble bathrooms, and classical Swiss service. Minutes from Chapel Bridge and old town attractions.', 8.3110, 47.0521);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (6, 3, 'Old Town Guesthouse', 120.00, 'Charming bed and breakfast in a renovated 16th-century building. Exposed wooden beams, antique furnishings, and homemade breakfast featuring local products.', 8.3065, 47.0510);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (7, 4, 'Lausanne Design Hotel', 210.00, 'Contemporary boutique hotel with modern art, rooftop terrace bar, and farm-to-table restaurant. Steps from the metro connecting to Olympic Museum and waterfront.', 6.6336, 46.5210);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (8, 5, 'St. Moritz Palace', 450.00, 'Iconic five-star hotel synonymous with luxury and elegance. Gourmet restaurants, champagne bar, spa with indoor pool, and impeccable service. Celebrity favorite since 1896.', 9.8381, 46.4970);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (9, 5, 'Mountain Comfort Inn', 180.00, 'Mid-range hotel offering great value with comfortable rooms, sauna, and hearty breakfast buffet. Easy access to ski slopes and hiking trails.', 9.8348, 46.5010);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (10, 6, 'Lugano Lakeside Retreat', 195.00, 'Modern hotel with Mediterranean-inspired design, rooftop pool, and Italian restaurant. Lake views, proximity to Parco Ciani, and vibrant nightlife nearby.', 8.9535, 46.0048);
INSERT INTO activities (id, destination_id, name, season, description, longitude, latitude) VALUES (1, 1, 'Gornergrat Railway Excursion', 'All Year', 'Scenic cogwheel train ride to 3,089m offering spectacular 360-degree views of the Matterhorn and 29 surrounding peaks. Observation platform, restaurant, and hiking trails at the summit.', 7.7844, 45.9839);
INSERT INTO activities (id, destination_id, name, season, description, longitude, latitude) VALUES (2, 2, 'Jungfraujoch - Top of Europe', 'All Year', 'Journey to Europe''s highest railway station at 3,454m. Ice Palace, Sphinx Observatory, and stunning views of the Aletsch Glacier. Alpine sensation and research exhibitions.', 7.9850, 46.5475);
INSERT INTO activities (id, destination_id, name, season, description, longitude, latitude) VALUES (3, 2, 'Paragliding Over Interlaken', 'Spring-Fall', 'Tandem paragliding flight over turquoise lakes and alpine valleys with professional pilots. No experience needed. Thrilling 20-30 minute flights with photo packages available.', 7.8632, 46.6863);
INSERT INTO activities (id, destination_id, name, season, description, longitude, latitude) VALUES (4, 3, 'Mount Pilatus Golden Round Trip', 'Spring-Fall', 'Combination journey via boat, cogwheel railway (world''s steepest), and aerial cableway. Summit activities include rope park, toboggan run, and panoramic restaurants.', 8.2540, 46.9797);
INSERT INTO activities (id, destination_id, name, season, description, longitude, latitude) VALUES (5, 4, 'Lavaux Vineyard Terraces Tour', 'Spring-Fall', 'UNESCO World Heritage wine region tour with tastings at family-run wineries. Walk through centuries-old terraced vineyards overlooking Lake Geneva with local Chasselas wines.', 6.7460, 46.4917);
INSERT INTO activities (id, destination_id, name, season, description, longitude, latitude) VALUES (6, 5, 'Bernina Express Scenic Train', 'All Year', 'UNESCO World Heritage railway journey through alpine passes, glaciers, and palm trees. From St. Moritz to Tirano, Italy, crossing 196 bridges and 55 tunnels in 4 hours.', 9.8390, 46.4983);
INSERT INTO destinations (id, name, region, description, longitude, latitude) VALUES (7, 'Zurich', 'Zurich', 'Switzerland''s largest city, set on Lake Zurich with a walkable old town, strong museum scene, lakeside promenades, shopping streets, and quick access to Uetliberg for city and alpine views.', 8.5417, 47.3769);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (11, 7, 'Zurich Old Town Boutique', 240.00, 'Quiet boutique hotel in Zurich''s old town with compact modern rooms, easy tram access, and walking distance to the Limmat river, Bahnhofstrasse, and lakeside promenades.', 8.5437, 47.3728);
INSERT INTO hotels (id, destination_id, name, price_per_night, description, longitude, latitude) VALUES (12, 7, 'Lake Zurich Guesthouse', 185.00, 'Relaxed guesthouse near the lake with simple bright rooms, breakfast, and quick access to boat piers, swimming spots, and evening walks along the waterfront.', 8.5484, 47.3603);
INSERT INTO activities (id, destination_id, name, season, description, longitude, latitude) VALUES (7, 7, 'Lake Zurich Promenade and Boat Cruise', 'All Year', 'Easy lakeside walk with optional boat cruise from Burkliplatz. Good for relaxed views, cafes, swimming areas in summer, and sunset over the lake and surrounding hills.', 8.5411, 47.3660);
INSERT INTO activities (id, destination_id, name, season, description, longitude, latitude) VALUES (8, 7, 'Uetliberg Panorama Hike', 'All Year', 'Short train ride and ridge walk above Zurich with broad views over the city, Lake Zurich, and the Alps on clear days. Popular for sunrise, sunset, and casual hiking.', 8.4910, 47.3495);
INSERT INTO activities (id, destination_id, name, season, description, longitude, latitude) VALUES (9, 7, 'Kunsthaus and Old Town Walk', 'All Year', 'City culture route combining the Kunsthaus art museum, Grossmunster, narrow old town lanes, riverside viewpoints, cafes, and independent shops.', 8.5480, 47.3702);
